{
  "scenario": "Прием наличных от двух клиентов подряд",
  "timeline": [
    {
      "t": 0.0,
      "event": "Кассир сидит за столом, дверь кассы закрыта, ноутбук открыт."
    },
    {
      "t": 2.5,
      "event": "Первый клиент открывает дверь и входит в кассовую зону."
    },
    {
      "t": 3.5,
      "event": "Кассир поворачивается к клиенту, дверь остается открытой."
    },
    {
      "t": 7.5,
      "event": "Клиент кладет на стол документ и наличные."
    },
    {
      "t": 8.0,
      "event": "Кассир берет документ, начинает осматривать."
    },
    {
      "t": 13.5,
      "event": "Кассир проверяет документ на детекторе подлинности."
    },
    {
      "t": 36.0,
      "event": "Кассир открывает сейф, кладет туда деньги и документ, закрывает сейф."
    },
    {
      "t": 43.5,
      "event": "Первый клиент встает и выходит из кассы."
    },
    {
      "t": 47.5,
      "event": "Дверь кассы закрывается."
    },
    {
      "t": 50.0,
      "event": "Второй клиент подходит к двери кассы."
    },
    {
      "t": 54.5,
      "event": "Второй клиент кладет на стол наличные."
    },
    {
      "t": 55.0,
      "event": "Кассир начинает пересчитывать деньги, документ от первого клиента еще лежит на столе."
    }
  ],
  "object_states": [
    {
      "object": "дверь",
      "t": 3.5,
      "state": "открыта (вход первого клиента)"
    },
    {
      "object": "дверь",
      "t": 47.5,
      "state": "закрыта"
    },
    {
      "object": "сейф",
      "t": 42.0,
      "state": "закрыт (после того как кассир от него отошел)"
    },
    {
      "object": "документ первого клиента",
      "t": 55.0,
      "state": "лежит на столе"
    },
    {
      "object": "наличные второго клиента",
      "t": 55.0,
      "state": "на столе"
    },
    {
      "object": "ноутбук",
      "t": 57.0,
      "state": "разблокирован (экран включен, активный рабочий стол)"
    }
  ],
  "violations": [
    {
      "type_id": "foreign_cash_on_desk",
      "timecode_sec": 54.5,
      "confidence": 0.95,
      "obs": "При обслуживании второго клиента на рабочем столе кассира остается документ и, вероятно, деньги от первого клиента (пачка банкнот, которые кассир еще не убрала в сейф, а только начала пересчитывать или осмотрела, но не спрятала до конца операции). Это создает риск смешения ценностей разных клиентов."
    },
    {
      "type_id": "no_client_id_check",
      "timecode_sec": 54.5,
      "confidence": 0.9,
      "obs": "Второй клиент кладет на стол только наличные, не предъявляя документ, удостоверяющий личность. Кассир принимает деньги, не требуя и не проверяя документ (в отличие от первого клиента, у которого кассир проверил документ)."
    }
  ]
